insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-001', '확인 필요', '적재화물목록 / 적하목록', '', 50, 'Charges · Customs', '관세법·고시의 정식 이름은 적재화물목록입니다. 실무에서는 적하목록(매니페스트)이 더 흔합니다. 기존 B/L·AWB 문서는 적하목록을 썼습니다. 어느 쪽으로 통일할까요?', '[]'::jsonb, '[{"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "통관 신고는 화주나 관세사가 하지만, 신고에 들어가는 선하증권(B/L)·항공화물운송장(AWB) 번호, 적재화물목록(적하목록), 선적·기적 일정은 포워더 손을 거칩니다."}, {"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "이 문서는 수출신고와 수입신고의 시기·기한, 세금이 계산되는 방식, HS 코드와 품목분류 사전심사, 그리고 적재화물목록 정정처럼 포워더가 직접 처리하는 일을 관세법과 관세청 고시 원문 기준으로 정리합니다."}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "포워더는 화물을 직접 검사하지 않고 화주의 인보이스·패킹리스트, 적재화물목록, 터미널·보세창고·운송사 기록으로 판단한다는 전제로 썼습니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-002', '확인 필요', '화물운송주선업자 / 포워더', '', 9, 'Charges · Customs', '관세법은 포워더를 화물운송주선업자라 부릅니다. 새 통관 문서는 법 조문을 설명할 때만 이 이름을 쓰고, 나머지는 포워더라고 썼습니다.', '[]'::jsonb, '[{"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "포워더(화물운송주선업자)"}, {"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "관세법은 포워더를 \"화물운송주선업자\"라 부릅니다."}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "적재화물목록 작성책임자는 마스터적재화물목록은 운항선사·운항항공사, 하우스적재화물목록은 화물운송주선업자(포워더)입니다(입출항 고시 제2조)."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-003', '확인 필요', '관세사등', '', 4, 'Customs', '관세사·관세법인·통관취급법인을 함께 부르는 법령 용어입니다. 처음 나올 때 풀어 썼습니다.', '[]'::jsonb, '[{"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "관세법 제242조는 수출·수입·반송 신고를 \"화주 또는 관세사등의 명의로\" 하도록 정합니다."}, {"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "관세사등은 관세사, 관세법인, 통관취급법인을 말합니다(관세법 제86조제1항제3호의 정의)."}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "신고인은 화주, 관세사등, 등록한 보세운송업자이고, 운송기간은 해상 10일, 항공 5일입니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-004', '확인 필요', '실중량 / 총중량', '', 27, 'Charges', '항공 운임 문서에서 Gross Weight를 실중량이라 썼습니다. 사이트의 다른 문서는 총중량을 씁니다(VGM, CTU). 항공 운임 맥락에서는 실중량이 실무에 가깝다고 보았습니다.', '[]'::jsonb, '[{"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "운임 중량은 실중량과 부피 중량 가운데 큰 값이고, 치수와 중량을 정해진 방식으로 반올림한 뒤에 정해집니다."}, {"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "① 운임 중량은 실중량과 부피 중량(가로 × 세로 × 높이 cm ÷ 6,000) 가운데 큰 값입니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-005', '확인 필요', '부피 중량 / 부피중량 / 용적중량', '', 28, 'Charges', 'Volume Weight. 사이트의 기존 표기(띄어 씀)를 따랐습니다.', '[]'::jsonb, '[{"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "운임 중량은 실중량과 부피 중량 가운데 큰 값이고, 치수와 중량을 정해진 방식으로 반올림한 뒤에 정해집니다."}, {"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "이 문서는 IATA 운임 규칙(TACT Rules)이 공개 자료에 인용된 범위와 항공사·규제기관의 공개 약관을 바탕으로 부피 중량 계산, 반올림, 여러 개 화물과 팔레트, 최소 운임과 중량 구간, AWB 운임 칸 읽는 법, House와 Master의 차이를 실제 숫자로 풀어 봅니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-006', '확인 필요', '운임 중량(Chargeable Weight)', '', 40, 'Charges', '기존 기준(과금 중량 ×)을 따랐습니다. C/W라고도 씁니다.', '[]'::jsonb, '[{"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "반대로 혼재 화물을 받은 화주는 \"House AWB 운임 중량과 Master AWB 운임 중량이 왜 다른가요\"라고 묻습니다."}, {"url": "/library/charges/ch-air-weight", "title": "항공 운임 중량 계산", "text": "두 질문 모두 항공 운임이 실제 무게가 아니라 운임 중량으로 계산된다는 데서 나옵니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-007', '확인 필요', '운임톤(R/T) / 레비뉴톤 / 프레이트톤', '', 6, 'Charges', 'Revenue Ton. 1CBM과 1,000kg 중 큰 쪽(W/M). 실무에서 "R/T"만 쓰는 경우가 많습니다.', '[]'::jsonb, '[{"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "운임과 부대비용도 컨테이너 단위가 아니라 운임톤(R/T, Revenue Ton) 단위로 계산하는 항목이 대부분이어서, 용적과 중량 중 어느 쪽이 기준이 되는지, CFS가 잰 숫자가 신고 숫자와 얼마나 다른지가 금액을 바꿉니다."}, {"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "이 문서는 LCL에 누가 관여하는지, 수출과 수입에서 화물이 어떤 순서로 움직이는지를 관세청 고시 기준으로 정리하고, 운임톤 계산과 공개된 한국 LCL 요율로 실제 숫자를 풀어 봅니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-008', '확인 필요', '콘솔사 / 혼재업체 / 콘솔리데이터', '', 20, 'Charges', 'LCL 화물을 모아 컨테이너를 채우는 업체(consolidator).', '[]'::jsonb, '[{"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "② 운임과 CFS 작업료·LCL 터미널 화물처리비(THC)·부두사용료·드레이지는 R/T당, 서류비·화물인도지시서(D/O) 비용·핸들링 비용은 B/L당 청구하는 구조가 많고, 금액과 최소 단위는 선사·콘솔사·CFS마다 다릅니다."}, {"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "LCL 요율은 공표 의무가 있는 선사 요금과 달리 콘솔사·CFS가 계약으로 정하는 부분이 많고 수시로 바뀌므로, 이 문서의 금액은 구조를 보여 주는 예시이며 실제 견적과 정산은 해당 회사의 최신 요율표를 따르십시오."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-009', '확인 필요', '코로더(co-loader)', '', 2, 'Charges', '자기 컨테이너 없이 다른 콘솔사 컨테이너에 화물을 싣는 포워더.', '[]'::jsonb, '[{"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "코로더(co-loader)"}, {"url": "/library/charges/ch-lcl", "title": "LCL·운임톤 계산", "text": "코로딩이 끼면 콘솔사의 House B/L 아래에 코로더의 House B/L이 다시 붙어, 화주가 가진 B/L 번호로는 선사나 콘솔사 시스템에서 조회되지 않는 일이 생깁니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-010', '확인 필요', '적출(devanning) / 디배닝', '', 15, 'Charges · Customs', '수입 CFS에서 컨테이너에서 화물을 꺼내는 작업.', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "수입자·수출자·생산자, 품명·규격·HS 코드, 협정세율·원산지·결정기준, 원산지증명서 발급번호·발급일·발급기관과 함께 적출국·적출항·출항일 , 환적국·환적항·환적일 이 들어갑니다."}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "보관이나 컨테이너 적출(devanning)이 있으면 비당사국 세관의 증빙서류도 필요"}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "Master B/L 단위 FCL, CFS에서 적출하지 않는 LCL은 Master B/L 단위 가능"}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-011', '확인 필요', '통과선하증권(through B/L) / 통선하증권', '', 5, 'Customs', 'FTA 직접운송 증빙 서류. 고시는 "통과선하증권"이라 씁니다.', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "수출 당사국에서 발행한 통과선하증권(through B/L) , 원산지증명서, 상업송장, 그 밖에 직접운송 요건 충족을 보여 주는 증빙서류"}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "한-아세안의 통과선하증권은 반드시 그 서류여야 하는지가 다퉈졌습니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-012', '확인 필요', '비가공증명서', '', 4, 'Customs', '경유국에서 가공하지 않았음을 보여 주는 서류(non-manipulation certificate).', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "경유국 세관 서류, 또는 AWB·B/L·복합운송서류, 원래 상업송장 사본, 재무 기록, 비가공증명서(non-manipulation certificate) 등 수입국 세관이 요구하는 서류"}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "홍콩 세관이 환적 화물을 감독하고 비가공증명서(Certificate of Non-manipulation)를 발급하며, 홍콩 세관 안내에 따르면 한국 관세청은 아시아태평양무역협정(APTA), 한-중 FTA, RCEP에 대해 이 증명서를 받아들입니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-013', '확인 필요', '제3국 송장 / 3국 송장', '', 3, 'Customs', '제3국 업체가 발행한 인보이스(third-country invoicing).', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "제3국 송장, 연결원산지증명서(back-to-back) 칸이 서식에 있습니다."}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "제3국 송장(third-country invoicing)"}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-014', '확인 필요', '연결원산지증명서(back-to-back)', '', 4, 'Customs', 'RCEP·한-아세안에서 중간 경유국이 발급하는 원산지증명서.', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "제3국 송장, 연결원산지증명서(back-to-back) 칸이 서식에 있습니다."}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "한-중은 운송상 분할을, RCEP 연결원산지증명서는 분할을 명시적으로 허용"}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-015', '확인 필요', '원산지증명서 / 원산지증명서(C/O)', '', 45, 'Customs', '새 문서는 약어 없이 원산지증명서라고만 썼습니다. 검색은 C/O로도 찾아집니다. 첫 등장에 (C/O)를 붙일까요?', '[]'::jsonb, '[{"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "원산지증명서·요건 서류 준비"}, {"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "수입통관 고시 제38조는 승인할 수 있는 경우로 완성품 세번으로 신고하려는 미조립 분할선적 물품, 사전세액심사 대상으로 세액결정에 오랜 시간이 걸리는 경우, 품목분류나 세율결정에 오랜 시간이 걸리는 경우, 수입신고 때 원산지증명서를 내지 못한 경우 등을 듭니다."}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "\"원산지증명서는 받았는데 왜 FTA 세율이 안 나오나요\", \"홍콩에서 환적했는데 괜찮나요\", \"B/L 선적항이 싱가포르로 찍혔는데 문제 되나요\"."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-016', '확인 필요', '협정관세 / FTA 관세', '', 27, 'Customs', 'FTA 특례법의 정식 이름은 협정관세입니다.', '[]'::jsonb, '[{"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "협정관세는 물품이 협정 원산지 요건을 충족하는 것만으로 나오지 않습니다."}, {"url": "/library/customs/cu-fta", "title": "FTA 원산지와 직접운송", "text": "이 문서는 협정관세 적용 요건, 원산지 결정기준, 협정별 증명 방식, 수입 쪽 신청과 검증, 직접운송 원칙과 B/L 문구, 자주 생기는 서류 실수를 정리하고 포워더 점검표로 마무리합니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-017', '확인 필요', '보세운송업자', '', 21, 'Customs', '관세법 제222조에 따라 등록한 업자. 포워더 지위만으로는 보세운송 신고인이 될 수 없다고 썼습니다.', '[]'::jsonb, '[{"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "이 문서는 관세법과 관세청 고시 원문을 기준으로 보세구역의 종류와 장치기간, 반입·반출신고와 화물관리번호, 보세운송의 신고·승인 구분, 신고인과 보세운송업자, 운송기간·담보·도착보고, 운송 중 사고의 관세 책임을 정리합니다."}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "신고인은 화주, 관세사등, 등록한 보세운송업자이고, 운송기간은 해상 10일, 항공 5일입니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-018', '확인 필요', '화물관리번호', '', 15, 'Charges · Customs', 'MRN·MSN·HSN을 합친 보세화물 관리번호.', '[]'::jsonb, '[{"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "House 입항 적재화물목록 자료 제공, 화물관리번호 안내"}, {"url": "/library/customs/cu-clearance", "title": "통관 절차와 HS 코드", "text": "적재화물목록관리번호에 Master·House 일련번호를 더한 것이 화물관리번호이고, 관세사는 이 번호로 화물을 특정해 수입신고를 합니다."}, {"url": "/library/customs/cu-bonded", "title": "보세구역과 보세운송", "text": "이 문서는 관세법과 관세청 고시 원문을 기준으로 보세구역의 종류와 장치기간, 반입·반출신고와 화물관리번호, 보세운송의 신고·승인 구분, 신고인과 보세운송업자, 운송기간·담보·도착보고, 운송 중 사고의 관세 책임을 정리합니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;
insert into public.term_review (id, grp, frm, dst, count, cats, note, sents, ctx, round) values ('r3-019', '확인 필요', '할증료 약어 영문 그대로(BAF·LSS·CAF…)', '', 43, 'Charges', '할증료 이름은 유류할증료(BAF)처럼 첫 등장에 한국어를 붙이고 그 뒤는 약어만 썼습니다.', '[]'::jsonb, '[{"url": "/library/charges/ch-surcharges", "title": "해상 할증료", "text": "\"운임은 따로 정했는데 인보이스에는 왜 BAF, LSS, ETS, PSS가 줄줄이 붙어 있나요?\" 포워더가 화주에게 가장 자주 듣는 질문입니다."}, {"url": "/library/charges/ch-surcharges", "title": "해상 할증료", "text": "1970년대에는 운임동맹이 항로마다 BAF·CAF 같은 몇 가지 조정 항목을 함께 정했지만, 2008년 EU가 운임동맹의 경쟁법 예외를 없앤 뒤로는 선사마다 이름과 공식, 적용일 기준을 따로 정하게 되었고 규제와 사건이 생길 때마다 새 항목이 늘었습니다."}]'::jsonb, 3) on conflict (id) do update set frm = excluded.frm, note = excluded.note, ctx = excluded.ctx, count = excluded.count, cats = excluded.cats;